/**
 * The Bridge graph's shape (plan §3). The file is generated by `node scripts/clubhouse/registry.mjs sync` into
 * docs/clubhouse/generated/bridge-graph.json; `clubhouse:check` holds it to its sources. Both the Bridge screens and
 * the signal route read it, so the browser never looks anything up.
 *
 * Plan: docs/superpowers/specs/helm-bridge/2026-11-18-clubhouse-bridge-redesign.md
 */

export type PageId = `P${number}`;
export type BridgeId = number;
export type IdStatus = 'implemented' | 'reserved' | 'deprecated';
export type Audience = 'coach' | 'player' | 'shared' | 'signed-out';

export interface GraphScreen {
  route: string;
  audience: Audience;
  name?: string;
  view?: string;
  coach?: string;
  player?: string;
  visitor?: string;
}

export interface GraphPage {
  name: string;
  slug: string;
  namespace: number;
  routes: string[];
  plannedRoutes: string[];
  roles: string[];
  gates: Record<string, string>;
  catalog: string | null;
  docs: Record<string, string | null>;
  held: { plan: string; status: string | null; migration: string | null }[];
  screens: GraphScreen[];
  /** Other pages' Bridge IDs this page's CONTRACT.md names: they may fire here without being a wrong page. */
  borrows: BridgeId[];
}

export interface GraphAction {
  page: PageId;
  label: string;
  component: string | null;
  handler: string | null;
  service: string | null;
  tables: string[];
  /** Outcome name (success, failure, offline, …) to the Bridge ID it lands on. */
  outcomes: Record<string, BridgeId>;
  tests: string[];
  /** The `useAction` name the client sends, once the emitters are wired (E2). */
  useActionName?: string;
}

export interface GraphId {
  ch?: string;
  page: PageId;
  category: number;
  name: string;
  meaning: string;
  status: IdStatus;
  where?: string[];
  tests?: string[];
  catalogRow?: { when?: string; theySee?: string; how?: string; test?: string };
}

export interface GraphFinding {
  page: PageId;
  screen: string;
  severity: 'S1' | 'S2' | 'S3' | 'S4';
  dimension: string;
  standard: string;
  title: string;
  repro: string;
  fix: string;
  files: string[];
  tier: 'W' | 'S' | 'D' | 'C';
  audit: string;
  status: 'open' | 'fixed' | 'withdrawn';
}

export interface BridgeGraph {
  version: 1;
  /** Names this exact contract; a release stamps its SHA beside it, so a signal is read against its own release. */
  contentHash: string;
  pages: Record<PageId, GraphPage>;
  surfaces: Record<string, { page: PageId | null; files: string[] }>;
  /** Empty until PR 2 numbers the controls (§4.7). */
  controls: Record<string, { page: PageId; label: string; actions: string[] }>;
  actions: Record<string, GraphAction>;
  ids: Record<string, GraphId>;
  tombstones: Record<string, { removedAt: string; replacement: BridgeId | null }>;
  chIndex: Record<string, BridgeId>;
  codeIndex: Record<string, string[]>;
  findings: Record<string, GraphFinding>;
  numberChecks: Record<PageId, { shown: string; expected: string; verdict: string; query: string; audit: string }[]>;
}

/** The shell's namespace: its IDs (offline, slow save, the frame) fire on every page. */
export const SHELL_PAGE: PageId = 'P001';
